-- BEGIN GENERATED REVIEWED ITEM SCALING
-- Generated by tools/item_scaling_overrides.py. Fresh bootstrap only.
DELIMITER //
CREATE PROCEDURE nightcap_reviewed_item_scaling()
BEGIN
 IF (SELECT COUNT(*) FROM items WHERE id=1001)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing reviewed item'; END IF;
 IF EXISTS(SELECT 1 FROM items WHERE id=1001 AND BINARY Name<>BINARY CONVERT(X'436c6f746820436170' USING utf8mb4)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reviewed item identity drift'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=1002)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing reviewed item'; END IF;
 IF EXISTS(SELECT 1 FROM items WHERE id=1002 AND BINARY Name<>BINARY CONVERT(X'436c6f7468205665696c' USING utf8mb4)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reviewed item identity drift'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=1003)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing reviewed item'; END IF;
 IF EXISTS(SELECT 1 FROM items WHERE id=1003 AND BINARY Name<>BINARY CONVERT(X'436c6f74682043686f6b6572' USING utf8mb4)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reviewed item identity drift'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=1004)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing reviewed item'; END IF;
 IF EXISTS(SELECT 1 FROM items WHERE id=1004 AND BINARY Name<>BINARY CONVERT(X'436c6f7468205368697274' USING utf8mb4)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reviewed item identity drift'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=1005)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing reviewed item'; END IF;
 IF EXISTS(SELECT 1 FROM items WHERE id=1005 AND BINARY Name<>BINARY CONVERT(X'436c6f746820536861776c' USING utf8mb4)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reviewed item identity drift'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=1006)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing reviewed item'; END IF;
 IF EXISTS(SELECT 1 FROM items WHERE id=1006 AND BINARY Name<>BINARY CONVERT(X'436c6f74682043617065' USING utf8mb4)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reviewed item identity drift'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=1007)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing reviewed item'; END IF;
 IF EXISTS(SELECT 1 FROM items WHERE id=1007 AND BINARY Name<>BINARY CONVERT(X'436c6f746820436f7264' USING utf8mb4)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reviewed item identity drift'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=1008)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing reviewed item'; END IF;
